import { MeshStandardNodeMaterial } from 'three/webgpu';
import {
  uv,
  mix,
  smoothstep,
  color,
  vec3,
  float,
  uniform,
  step,
  oneMinus,
  sin,
  fract,
  dot,
  vec2,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, DoubleSide } = THREE;

  const group = new Group();
  group.name = 'hub-pricing-card-0-label';

  // ---- palette tokens ----
  const INK = '#16161d';
  const SURFACE = '#0b0b10';
  const PAPER = '#e8ecf2';
  const ACCENT = '#ff2a38';

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? {
    text: 'Pricing 3',
    typography: { fontSize: 39 },
  };
  const labelText = headlineItem.text ?? 'Pricing 3';
  const fontSize = headlineItem.typography?.fontSize ?? 39;

  // ---- background chip geometry ----
  const width = 1.4;
  const height = 0.5;
  const geometry = new PlaneGeometry(width, height, 1, 1);

  const material = new MeshStandardNodeMaterial({
    side: DoubleSide,
    roughness: 0.55,
    metalness: 0.3,
    transparent: true,
  });

  const uvNode = uv();

  // engineered vertical gradient: ink -> surface
  const gradient = mix(color(INK), color(SURFACE), uvNode.y);

  // thin accent underline band near the bottom of the chip
  const bandLow = smoothstep(0.06, 0.09, uvNode.y);
  const bandHigh = oneMinus(smoothstep(0.1, 0.13, uvNode.y));
  const accentBand = bandLow.mul(bandHigh);

  // static, subtle grain (no time dependency -> stays static composition)
  const grainSeed = dot(uvNode, vec2(12.9898, 78.233));
  const grain = fract(sin(grainSeed).mul(43758.5453)).sub(0.5).mul(0.035);

  const baseColor = mix(gradient, color(ACCENT), accentBand.mul(0.9));
  const finalColor = baseColor.add(vec3(grain, grain, grain));

  const opacityUniform = uniform(0);

  material.colorNode = finalColor;
  material.emissiveNode = mix(vec3(0.0, 0.0, 0.0), color(ACCENT), accentBand.mul(0.35));
  material.opacityNode = opacityUniform;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, 0, 0);
  group.add(mesh);

  // ---- label text (rendered via MSDF atlas, verbatim spec copy) ----
  const textNode = ctx.fontAtlas.createText(labelText, {
    fontSize,
    color: PAPER,
    align: 'center',
  });
  textNode.position.set(0, 0.03, 0.01);
  group.add(textNode);

  // static composition => single, restrained entrance motion only (weighted-settle)
  group.scale.set(0.96, 0.96, 0.96);

  const tl = gsap.timeline();
  tl.to(opacityUniform, { value: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(
    group.scale,
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power3.out' },
    0
  ).to(group.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'power4.out' });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    geometry.dispose();
    material.dispose();
    if (textNode.geometry) textNode.geometry.dispose();
    if (textNode.material) {
      if (Array.isArray(textNode.material)) {
        textNode.material.forEach((m) => m.dispose());
      } else {
        textNode.material.dispose();
      }
    }
  };

  return group;
}
